import sys

# VALUES is provided by the execution environment.
# It maps placeholder names (e.g., "T1") to concrete values.
# Do NOT modify or reassign VALUES.

def resolve(val):
    """Resolve a placeholder using VALUES if needed."""
    while isinstance(val, str) and val in VALUES:
        val = VALUES[val]
    return val

def time_to_min(t):
    """Convert 'H:MM' or 'HH:MM' to minutes since midnight."""
    h, m = map(int, t.split(":"))
    return h * 60 + m

def min_to_time(m):
    """Convert minutes since midnight to zero‑padded 'HH:MM'."""
    h = m // 60
    mm = m % 60
    return f"{h:02d}:{mm:02d}"

def merge_intervals(intervals):
    """Merge overlapping or adjacent intervals."""
    if not intervals:
        return []
    intervals.sort()
    merged = [intervals[0]]
    for cur in intervals[1:]:
        prev = merged[-1]
        if cur[0] <= prev[1]:          # overlap or touch
            merged[-1] = (prev[0], max(prev[1], cur[1]))
        else:
            merged.append(cur)
    return merged

def invert_intervals(busy, day_start=0, day_end=24*60):
    """Return free intervals given a list of busy intervals within a day."""
    free = []
    prev_end = day_start
    for s, e in busy:
        if s > prev_end:
            free.append((prev_end, s))
        prev_end = max(prev_end, e)
    if prev_end < day_end:
        free.append((prev_end, day_end))
    return free

# ----------------------------------------------------------------------
# 1. Identify participants (keys ending with "_meetings")
participants = []
for key in VALUES:
    if key.endswith("_meetings"):
        participants.append(key[:-len("_meetings")])

# 2. Build busy‑interval map: day -> list of (start_min, end_min)
busy_by_day = {}

def add_busy(day, start, end):
    day = resolve(day)
    start = resolve(start)
    end = resolve(end)
    if not (isinstance(day, str) and isinstance(start, str) and isinstance(end, str)):
        return
    s_min = time_to_min(start)
    e_min = time_to_min(end)
    busy_by_day.setdefault(day, []).append((s_min, e_min))

# 3. Add participants' meetings
for p in participants:
    meetings = VALUES.get(f"{p}_meetings", [])
    for entry in meetings:
        # each entry is expected to be a 3‑tuple (day_key, start_key, end_key)
        if len(entry) != 3:
            continue
        d_key, s_key, e_key = entry
        add_busy(d_key, s_key, e_key)

# 4. Add "not before" constraints if present (treated as busy from midnight)
for p in participants:
    nb = VALUES.get(f"{p}_not_before")
    if nb:
        # expected (day_key, time_key)
        if isinstance(nb, (list, tuple)) and len(nb) == 2:
            d_key, t_key = nb
            day = resolve(d_key)
            t = resolve(t_key)
            if isinstance(day, str) and isinstance(t, str):
                add_busy(day, "0:00", t)   # busy from start of day until the limit

# 5. Add work‑window / allowed‑window constraints (if any)
# Look for keys like "<prefix>_window_day"
for key in list(VALUES):
    if key.endswith("_window_day"):
        prefix = key[:-len("_window_day")]
        day_key = VALUES[key]
        start_key = VALUES.get(f"{prefix}_window_start")
        end_key = VALUES.get(f"{prefix}_window_end")
        if start_key and end_key:
            # before start is busy, after end is busy on that day
            day = resolve(day_key)
            start = resolve(start_key)
            end = resolve(end_key)
            if isinstance(day, str) and isinstance(start, str) and isinstance(end, str):
                # busy before start
                add_busy(day, "0:00", start)
                # busy after end
                add_busy(day, end, "24:00")

# 6. Determine meeting duration (minutes)
duration_val = VALUES.get("D1")
duration = resolve(duration_val)
if isinstance(duration, str) and duration.isdigit():
    duration = int(duration)
elif isinstance(duration, (int, float)):
    duration = int(duration)
else:
    # fallback: try to find any integer in VALUES
    duration = 0

# 7. Determine candidate days.
# Prefer a specific day if a placeholder like "Day1" exists.
candidate_days = set(busy_by_day.keys())
if "Day1" in VALUES:
    candidate_days.add(resolve("Day1"))

# 8. Search for earliest feasible slot.
solution = None
for day in sorted(candidate_days):
    busy = merge_intervals(busy_by_day.get(day, []))
    free = invert_intervals(busy)
    for s, e in free:
        if e - s >= duration:
            start_min = s
            end_min = s + duration
            solution = [day, min_to_time(start_min), min_to_time(end_min)]
            break
    if solution:
        break

# If still no solution, try any day of week (Monday‑Sunday) with empty busy list.
if not solution:
    all_weekdays = ["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"]
    for day in all_weekdays:
        busy = merge_intervals(busy_by_day.get(day, []))
        free = invert_intervals(busy)
        for s, e in free:
            if e - s >= duration:
                solution = [day, min_to_time(s), min_to_time(s+duration)]
                break
        if solution:
            break

# Print the answer in the required format.
print(solution)
